1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = QuoteResult | ClaimResult;
37	
38	export interface QuoteResult {
39	  premium: number;
40	}
41	
42	export interface ClaimResult {
43	  payout: number;
44	  remainingCap: number;
45	}
46	
47	export interface ScenarioResult {
48	  results: Result[];
49	}
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	// Base premium for a single item of each type.
54	const UNIT_BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const CURSE_SURCHARGE_RATE = 1 / 2;
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	  for (const item of items) {
70	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
71	  }
72	  return counts;
73	};
74	
75	// A building block of 3 alike components is offered at a special base premium.
76	const basePremiumForAlikeItems = (type: string, count: number): number =>
77	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * UNIT_BASE_PREMIUMS[type];
78	
79	const policyBasePremium = (items: Item[]): number =>
80	  [...countByType(items)].reduce(
81	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
82	    0,
83	  );
84	
85	// Item-specific modifiers apply to the base premium of the affected item.
86	const itemSurcharges = (items: Item[]): number =>
87	  items.reduce(
88	    (total, item) =>
89	      total + (item.cursed ? UNIT_BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
90	    0,
91	  );
92	
93	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
94	// separate term rather than folded into a `base * 1.1` factor, which is not
95	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
96	const quotePremium = (items: Item[]): number => {
97	  const base = policyBasePremium(items);
98	  return Math.ceil(
99	    base +
100	      itemSurcharges(items) +
101	      base * FIRST_INSURANCE_SURCHARGE_RATE +
102	      PROCESSING_FEE,
103	  );
104	};
105	
106	const quote = (step: QuoteStep): QuoteResult => ({
107	  premium: quotePremium(step.items),
108	});
109	
110	const runStep = (step: Step): Result => {
111	  switch (step.op) {
112	    case "quote":
113	      return quote(step);
114	    default:
115	      throw new Error(`unsupported step: ${step.op}`);
116	  }
117	};
118	
119	export const runScenario = (scenario: Scenario): ScenarioResult => ({
120	  results: scenario.steps.map(runStep),
121	});
